INSERT INTO `feedback` (`fb_id`, `names`, `email`, `user_type`, `telephone`, `subject`, `rating`, `company`, `message`, `published`, `created_at`) VALUES
(1, 'Kwizigira Kevin', 'kwizigira2kevin@gmail.com', 'Visitor', '0785060800', 'Membership', '4', 'Venus Tech Solutions', 'PSF Rwanda has been a vital partner in the growth of my tech startup. Their exhibitions have connected me with potential clients and investors, leading to significant business growth. The organization\'s commitment to promoting innovation and technology is evident in every aspect of their work.\n\nIn addition to the exhibitions, PSF Rwanda\'s advocacy work has played a crucial role in shaping policies that support the growth of the tech sector in Rwanda.\n\nI\'m proud to be a member of the PSF Rwanda community and I look forward to continuing to work with them to drive innovation and economic growth in Rwanda.PSF Rwanda has been a vital partner in the growth of my tech startup. Their exhibitions have connected me with potential clients and investors, leading to significant business growth. The organization\\\'s commitment to promoting innovation and technology is evident in every aspect of their work.\n\nIn addition to the exhibitions, PSF\\\'s advocacy work has played a crucial role in shaping policies that support the growth of the tech sector in Rwanda.\n\nI\\\'m proud to be a member of the PSF Rwanda community and I look forward to continuing to work with them to drive innovation and economic growth in Rwanda.', 1, '2024-11-22 02:13:04'),
(2, 'Ineza Uwera Ange', 'kaneza500@gmail.com', 'Visitor', '0782500400', 'Exhibition', '4', 'Kaneza Creations', 'As a small business owner, I\\\'ve found PSF Rwanda to be an invaluable resource. Their biannual exhibitions have provided me with a fantastic platform to showcase my handcrafted jewelry to a wider audience. The organization\\\'s dedication to promoting local businesses is evident in their efforts to attract both local and international visitors. Beyond the exhibitions, PSF Rwanda\\\'s advocacy work has been instrumental in addressing the challenges faced by small businesses in Rwanda. Their lobbying efforts have resulted in policies that support entrepreneurship and create a favorable business environment.', 1, '2024-11-27 12:30:13'),
(3, 'Nshimiyimana Jean Luc', 'nshimiye.jeanluc3@gmail.com', 'Visitor', '0785439902', 'Advocacy', '5', 'Nshimye Agro-Processing Ltd', 'As a fashion designer, PSF Rwanda has provided me with the perfect platform to showcase my creations to the world. Their exhibitions have attracted a diverse audience, including fashion enthusiasts, buyers, and media representatives.', 1, '2024-12-01 19:59:11'),
(4, 'Vince Reagan', 'vince.reagan@gmail.com', 'Visitor', '+254717165952', 'Membership', '1', 'Vince Reagan', 'Dear Psf%2C%0D%0A%0D%0AHope you%27re doing well. Is your website https://psf.org.rw/ fully optimized and ready for business success%3F As a digital marketer and web developer%2C I%E2%80%99d love to offer you a free website audit to help enhance your online presence.%0D%0A%0D%0AOur team will provide actionable insights to improve performance%2C visibility%2C and user experience.%0D%0A%0D%0AFor quick communication and support%2C connect with me here: https://rebrand.ly/imrulrp.%0D%0A%0D%0AInvesting in your website%E2%80%99s performance means investing in your business%E2%80%99s success. Let%E2%80%99s work together to maximize its impact%21%0D%0A%0D%0ABest regards%2C%0D%0ATemmy%0D%0A%ED%A0%BD%ED%B3%A7 info%40tblaqhustle.com', 0, '2025-04-14 09:46:11'),
(5, 'Minda Turriff', 'minda.turriff@gmail.com', 'Visitor', '30994632', 'BRC', '1', 'Minda Turriff', 'We are currently seeking companies like yours for a potential long-term partnership. Could you kindly share your product offerings along with pricing details? Please  contact me on WhatsApp: +44 758 789 0515', 0, '2025-04-16 18:23:12');
