INSERT INTO `membership_reg_type` (`id`, `name`, `description`) VALUES
(1, 'TIN', 'Taxpayer Identification Number(TIN) is a unique number which is issued to a taxpayer by the tax Administration. It is obligatory for every taxpayer to have this unique number. Taxpayers have the obligation to indicate this number on all correspondences they do with RRA. This number has to be indicated on all documents which the taxpayer provides to the tax administration as proof)\r\n\r\nNote that TIN is offered free of charge and it is issued within about 5 minutes after submission of the required papers.'),
(2, 'Company Code', 'Company code is a unique company ID that is given by your local government when registering a legal entity. It identifies a certain company on invoices and similar legal issues.'),
(3, 'Patent', 'Patent is a type of intellectual property that gives its owner the legal right to exclude others from making, using, or selling an invention for a limited period of time in exchange for publishing an enabling disclosure of the invention.'),
(4, 'RCA Number', 'Root cause analysis (RCA) is the process of finding and analyzing the causes of a problem or an event impacting the value delivery of an application or an organization. RCA can find one or more root causes underlying a problem needing to be addressed to solve and prevent the problem from recurring.');
