INSERT INTO `publication` (`pub_id`, `title`, `description`, `pub_file`, `pub_date`) VALUES
(1, 'Ministry of Trade and Industry (Rwanda Industrial Policy) in April 2011', 'This document shares a lot about Industrial Policy which has three objectives including:\r\n1) Increase domestic production for local consumption\r\n2) Improve Rwanda’s export competitiveness\r\n3) Create an enabling environment for Rwanda’s industrialization', 'pdoc-1730101312698.pdf', '2024-10-28 09:41:52'),
(2, 'Made-In-Rwanda Policy in November 2017', 'This document shows Made-in-Rwanda policy by MINICOM in November @ 2017', 'pdoc-1730101908277.pdf', '2024-10-28 09:51:48'),
